import{I as e,P as t,Q as n,n as r}from"./chunks/framework.BmaFRZVf.js";var i=JSON.parse(`{"title":"Record Validation and Workflow Status","description":"","frontmatter":{"id":"guide.record-validation","title":"Record Validation and Workflow Status"},"headers":[],"relativePath":"guides/record-validation.md","filePath":"guides/record-validation.md"}`),a={name:`guides/record-validation.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="record-validation-and-workflow-status" tabindex="-1">Record Validation and Workflow Status <a class="header-anchor" href="#record-validation-and-workflow-status" aria-label="Permalink to “Record Validation and Workflow Status”">​</a></h1><p><code>mise run validate</code> checks the current record metadata. <code>mise run status</code> identifies the active proposal and the next actor. This page is their current public contract; the <a href="./../PROCESS">process</a> defines the surrounding workflow.</p><h2 id="validate-the-record" tabindex="-1">Validate the record <a class="header-anchor" href="#validate-the-record" aria-label="Permalink to “Validate the record”">​</a></h2><p>Run <code>mise run validate</code> from the repository root. Success prints <code>Validation passed: 0 violations</code> and exits zero. A failure identifies the file and problem, prints the violation count, and exits nonzero. <code>mise run validate -- --json</code> returns a JSON object with <code>violations</code> (file paths and messages) and <code>count</code>.</p><p>The validator reads <code>VISION.md</code> and Markdown files directly inside <code>proposals/</code>, <code>policies/</code>, <code>decisions/</code>, and <code>guides/</code>. Directory READMEs are indexes, not records. Empty or absent optional record directories are allowed. Nested Markdown records are rejected. Symlinked regular files are checked; symlinked directories are not traversed.</p><table tabindex="0"><thead><tr><th>Record</th><th>Required frontmatter</th><th>Allowed status</th></tr></thead><tbody><tr><td>Vision</td><td><code>title</code>, <code>updated</code> as <code>YYYY-MM-DD</code></td><td>None</td></tr><tr><td>Proposal</td><td><code>id</code>, <code>title</code>, non-empty <code>authors</code> list, <code>status</code>, <code>pull-request</code>, <code>supersedes</code> list</td><td><code>draft</code>, <code>awaiting-implementation</code>, <code>active-review</code>, <code>returned-for-revisions</code>, <code>accepted</code>, <code>implemented</code>, <code>rejected</code>, <code>withdrawn</code>, <code>superseded</code></td></tr><tr><td>Policy</td><td><code>id</code>, <code>title</code>, <code>status</code></td><td><code>draft</code>, <code>active</code></td></tr><tr><td>Decision</td><td><code>id</code>, <code>title</code>, <code>status</code></td><td><code>proposed</code>, <code>accepted</code></td></tr><tr><td>Guide</td><td><code>id</code>, <code>title</code></td><td>None</td></tr></tbody></table><p>Proposal, policy, and decision filenames use <code>&lt;NNNN&gt;-&lt;slug&gt;.md</code>, with IDs such as <code>policy.0001</code>. Guides use kebab-case filenames and IDs such as <code>guide.record-validation</code>. IDs must match their filenames and be unique. Frontmatter supports scalar values and inline lists; duplicate keys and malformed lists are errors. Proposal <code>issues</code>, when present, is an inline list.</p><p>Policies and decisions may carry <code>established-by: proposal.&lt;NNNN&gt;</code> as historical provenance. It must be a scalar reference to an existing proposal. It remains optional when a record changes in place. A current policy or decision cannot contain <code>supersedes</code> or use <code>status: superseded</code>; the error explains how to revise or retire it instead. These fields still describe historical relationships between proposals. A replacement proposal names its predecessor in <code>supersedes</code>, that predecessor is marked <code>superseded</code>, and the relationship must not form a cycle.</p><p>Guides use ordinary links to their current sources. The obsolete <code>describes</code> field is rejected with migration guidance. The validator checks metadata references; the documentation build checks local Markdown links. Run the full <code>mise run check</code> before publishing a retirement, because metadata validation alone cannot detect a broken prose link.</p><p>An unresolved clarification marker in proposal prose blocks <code>awaiting-implementation</code>, <code>active-review</code>, <code>accepted</code>, <code>implemented</code>, and <code>superseded</code>. Draft, returned, rejected, and withdrawn proposals may contain unresolved questions. Inline code and fenced examples of the marker are ignored.</p><h2 id="revise-and-retire-a-policy" tabindex="-1">Revise and retire a policy <a class="header-anchor" href="#revise-and-retire-a-policy" aria-label="Permalink to “Revise and retire a policy”">​</a></h2><p>A current policy can start with:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">---</span></span>
<span class="line"><span style="--shiki-dark:#85E89D;--shiki-light:#11782a;">id</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">policy.0001</span></span>
<span class="line"><span style="--shiki-dark:#85E89D;--shiki-light:#11782a;">title</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">Preserve User Focus</span></span>
<span class="line"><span style="--shiki-dark:#85E89D;--shiki-light:#11782a;">status</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">active</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">---</span></span></code></pre></div><p>Revise its rule and applicable checks in the same change, keeping its logical identity. No replacement policy or supersession entry is needed. When the policy ceases to apply, repair its current links and remove the file. Preserve any historical link that still matters by pointing it at the Git revision that contains the old policy. See <a href="./keeping-the-record">Keeping the Record</a> for the human decision and migration procedure.</p><h2 id="find-the-next-actor" tabindex="-1">Find the next actor <a class="header-anchor" href="#find-the-next-actor" aria-label="Permalink to “Find the next actor”">​</a></h2><p>Run <code>mise run status</code> with no arguments. It reads the branch, pull request, and active proposal, then reports the phase, situation, next action, and whether the agent or human acts next. <code>mise run status -- --json</code> provides the same facts and derived guidance as JSON.</p><p>An approved proposal routes to updating current specifications, then failing tests, guides, implementation, and review. The human still owns approval to implement and acceptance of the result. <code>implemented</code> records accepted implementation before merge; it does not prove integration or release. A closed, unmerged PR with accepted work requires human reconciliation rather than being treated as delivered.</p><p>Missing or unavailable GitHub state is reported as unknown rather than assumed to mean that no pull request exists. Ambiguous proposal selection, unresolved questions, unpushed commits, and disagreement between PR draft state and proposal review state appear as notices. See <a href="./running-a-feature">Running a Feature</a> for the phase-by-phase process.</p><h3 id="beads-in-the-status-report" tabindex="-1">Beads in the status report <a class="header-anchor" href="#beads-in-the-status-report" aria-label="Permalink to “Beads in the status report”">​</a></h3><p>Before reporting, <code>mise run status</code> runs one Beads sync with the project&#39;s remote, the same one <code>mise run beads:sync</code> runs, limited to 20 seconds. After the phase report it adds a Beads section: the sync outcome, ready work from <code>bd ready</code>, the items in progress and who holds them from <code>bd list --status in_progress</code>, and the project&#39;s memories from <code>bd prime --memories-only</code>. The ready work, items in progress, and memories are this machine&#39;s replica after the sync.</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Meaning</th><th>Reported with</th></tr></thead><tbody><tr><td><code>synced</code></td><td>This replica pulled every change on the remote and published its own.</td><td>One line.</td></tr><tr><td><code>failed</code></td><td>The sync did not finish: the remote was unreachable, authentication failed, push retries ran out, or 20 seconds passed. It also fails, without pulling or pushing, when the Beads remote is not the same repository as the checkout&#39;s <code>origin</code>.</td><td>The reason, and that the rest of the section shows this machine&#39;s state.</td></tr><tr><td><code>conflict</code></td><td>Beads halted on a conflict it cannot settle; nothing was pushed.</td><td>The conflicted tables Beads names, and the items that differ between this replica and the remote.</td></tr><tr><td><code>blocked</code></td><td>A dirty working set stops Beads from publishing; nothing was pushed.</td><td>Beads&#39; explanation.</td></tr><tr><td><code>unavailable</code></td><td><code>bd</code> is not installed, there is no Beads workspace, its database is not initialized, or reading it after the sync failed.</td><td>The reason and a pointer to <code>mise run setup</code>, in place of the whole section. When a read failed, the reason names it and keeps the sync&#39;s outcome.</td></tr></tbody></table><p>Beads outcomes never change the exit status of <code>mise run status</code>. With <code>--json</code>, the object gains a <code>beads</code> key holding either <code>sync</code> (<code>outcome</code> and <code>detail</code>), <code>ready</code> (a list of <code>id</code>, <code>title</code>, and <code>priority</code>), <code>in_progress</code> (a list of <code>id</code>, <code>title</code>, and <code>assignee</code>), and <code>memories</code> (text); or <code>unavailable</code> (the reason). The <code>tracking-work</code> skill in <code>.agents/skills/</code> says how an agent responds to each outcome.</p><h2 id="what-these-commands-do-not-establish" tabindex="-1">What these commands do not establish <a class="header-anchor" href="#what-these-commands-do-not-establish" aria-label="Permalink to “What these commands do not establish”">​</a></h2><p>The checks cannot decide whether a specification states the right behavior, a test asserts enough, or a policy is still needed. Review those claims against the current requirements and human-approved intent. Gherkin bindings, native schemas, API examples, and platform checks use the project&#39;s own tools. Workbench introduces no universal specification registry or mandatory Gherkin runner.</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};